/* The C99 declarations benchmark input.
 *
 * Designated initialisers for members and elements, compound literals,
 * arrays whose length the program works out -- local, and as parameters
 * with restrict beside them -- declarations after statements and in for,
 * _Bool, inline, auto, an enum with values of its own, and a struct that
 * ends in an array with no size. What C99 added to declaring things, which
 * the older inputs have little or none of.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

struct point_anchor { int x, y, z; };

static const int table_anchor[8] = { [2] = 0, [5] = 7, [7] = 1 };

int design_anchor(int base) {
    struct point_anchor point = { .z = base, .x = 0 };
    struct point_anchor list[3] = { [1] = { .y = 4 }, [0].x = 2 };

    return point.x + point.y + point.z + list[1].y + list[0].x
           + table_anchor[2] + table_anchor[5];
}

struct pair_buffer { int first, second; };

static int sum_buffer(const struct pair_buffer *pair) {
    return pair->first + pair->second;
}

int literal_buffer(int base) {
    int *row = (int[]){ base, base + 1, base + 1 };
    struct pair_buffer copy = (struct pair_buffer){ .second = row[2], .first = 3 };

    return sum_buffer(&(struct pair_buffer){ base, 2 }) + copy.first
           + copy.second + row[1];
}

int grid_cursor(int size) {
    int grid[size][size + 1];
    int total = 0;

    for (int row = 0; row < size; row++)
        for (int column = 0; column <= size; column++)
            grid[row][column] = row + column;
    for (int row = 0; row < size; row++)
        total += grid[row][size - row];

    return total + (int) (sizeof grid / sizeof grid[0][0]);
}

static void fill_header(int rows, int columns, int cells[rows][columns],
                   int *restrict last) {
    for (int row = 0; row < rows; row++)
        for (int column = 0; column < columns; column++)
            cells[row][column] = row * columns + column;
    *last = cells[rows - 1][columns - 1];
}

int shape_header(int rows) {
    int cells[rows][3];
    int last = 0;

    fill_header(rows, 3, cells, &last);

    return last + cells[0][1];
}

static inline _Bool even_margin(int value) { return !(value & 1); }

int count_margin(int limit) {
    auto int seen = 0;

    for (int value = 0; value < limit; value++) {
        _Bool even = even_margin(value);

        if (!even)
            continue;
        seen++;
        int bonus = value > 4 ? 1 : 0;
        seen += bonus;
    }
    const _Bool many = seen > 2;

    return seen + many;
}

enum level_marker { LOW_MARKER5 = 1, MIDDLE_MARKER5 = 4, HIGH_MARKER5 = MIDDLE_MARKER5 * 2 };

struct packet_marker {
    int size;
    unsigned char data[];
};

int grade_marker(int value) {
    static union {
        struct packet_marker packet;
        unsigned char bytes[sizeof(struct packet_marker) + 4];
    } storage;
    struct packet_marker *packet = &storage.packet;

    packet->size = 4;
    for (int i = 0; i < packet->size; i++)
        packet->data[i] = (unsigned char) (value + i);
    enum level_marker level = value > 5 ? HIGH_MARKER5 : value > 2 ? MIDDLE_MARKER5 : LOW_MARKER5;
    switch (level) {
    case LOW_MARKER5:
        return packet->data[0];
    case MIDDLE_MARKER5:
        return packet->data[1] + 1;
    default:
        return packet->data[3] + HIGH_MARKER5;
    }
}

